import os
from ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions import DataTransferAppServerException, DataTransferCreationException
from . import app_server
from . import ue_pc_server
from . import dummy_server
from ute_ue.utils import param_checker
from ta_ue_plugin_qualcomm.ue.qualcomm.data_transfer.data_transfer_command_factory import prepare_command_tails
import ute_common_abstract_core.logger as core_logging
import logging


UNIT_OF_DT_DEFINITION_THROUGHPUT = 'Kbits/sec'
UNIT_OF_DT_DEFINITION_BANDWIDTH = 'k'


def data_transfer_factory(app_server_config, ue, data_transfer_name, dt_definition):
    """
    :param app_server_config:   dictionary with application server config
    :param ue:                  ue instance
    :param data_transfer_name: name for data transfer
    :param dt_definition:       data transfer definition
    :return:                    sender and receiver instances
    """
    # Extract data from UE
    ue_type = ue.ue_type
    ue_pc = ue.ue_pc_handler
    ue_serial_number = ue.serial_number
    ue_name = ue.name
    ue_ip = ue.ip
    ue_iperf_adb_dir = ue.iperf_adb_dir
    ue_iperf_version = 'None'
    logger = logging.getLogger("ute_ue.ue.{}_{}.debug".format(ue.name, data_transfer_name))
    dt_name = data_transfer_name

    # Extract data from App Server
    try:
        app_srv_hostname = app_server_config['ssh']["host"]
        app_srv_username = app_server_config['ssh']["user"]
        app_srv_password = app_server_config['ssh']["password"]
        app_srv_lte_ip = app_server_config["lte_network_ip"]
    except KeyError:
        raise DataTransferAppServerException("Unable to get all required App Server parameters.")

    # Performing validation of parameters
    validate_params_consistency(ue_type, dt_definition, ue_iperf_adb_dir, ue_serial_number)
    source_ip, target_ip = get_source_and_target_ip(dt_definition.direction, app_srv_lte_ip, ue_ip)
    logger.info("Source IP for data transfer commands set to: {}".format(source_ip))
    logger.info("Target IP for data transfer commands set to: {}".format(target_ip))
    sender_cmd_tail, receiver_cmd_tail = prepare_command_tails(ue_type, target_ip, source_ip, dt_definition)

    sender = None
    receiver = None
    # Analyzer parameters
    analyzer_params = {
        # 'start_step': kwargs.get('start_step', 5),
        'threshold': dt_definition.protocol_details.get('stability_threshold', 10),
        'lines_to_log_after_drop': dt_definition.protocol_details.get('lines_to_log_after_drop', 10)
    }

    if dt_definition.protocol.upper() in ['ICMP']:

        dt_definition.protocol = 'PING'  # compatibility with ue_pc_server on UE_PC side
        verification_delay = int(dt_definition.protocol_details.get('verification_delay', 1))
        analyzer_params['start_step'] = verification_delay
        if dt_definition.direction.upper() == "UL":
            receiver = ue_pc_server.PingDataTransfer(ue_name=ue_name,
                                                     dt_name=dt_name,
                                                     dt_direction=dt_definition.direction,
                                                     command_tail=receiver_cmd_tail,
                                                     ue_pc_instance=ue_pc,
                                                     ue_id=ue_serial_number,
                                                     ue_ip=ue_ip,
                                                     ue_type=ue_type,
                                                     app_srv_lte_ip=app_srv_lte_ip,
                                                     analyzer_params=analyzer_params,
                                                     verification_delay=verification_delay)

            sender = dummy_server.DummyServer()  # Just to keep consistency
        else:
            receiver = app_server.PingDataTransfer(command_tail=receiver_cmd_tail,
                                                   app_server_ip=app_srv_hostname,
                                                   app_server_username=app_srv_username,
                                                   app_server_password=app_srv_password,
                                                   app_server_lte_ip=app_srv_lte_ip,
                                                   logger=logger,
                                                   analyzer_params=analyzer_params
                                                   )
            sender = dummy_server.DummyServer()  # Just to keep consistency

    elif dt_definition.protocol.upper() in ['TCP', 'UDP']:

        verification_delay = int(dt_definition.protocol_details.get('verification_delay', 10))
        analyzer_params['start_step'] = verification_delay
        if dt_definition.direction.upper() == "UL":
            analyzer_params['start_step'] = verification_delay
            receiver = app_server.IperfDataTransfer(app_server_ip=app_srv_hostname,
                                                    app_server_username=app_srv_username,
                                                    app_server_password=app_srv_password,
                                                    app_server_lte_ip=app_srv_lte_ip,
                                                    logger=logger,
                                                    command_tail=receiver_cmd_tail,
                                                    analyzer_params=analyzer_params)

            sender = ue_pc_server.IperfDataTransfer(ue_name=ue_name,
                                                    dt_name=dt_name,
                                                    dt_protocol=dt_definition.protocol,
                                                    dt_direction=dt_definition.direction,
                                                    ue_pc_instance=ue_pc,
                                                    ue_id=ue_serial_number,
                                                    ue_ip=ue_ip,
                                                    ue_type=ue_type,
                                                    command_tail=sender_cmd_tail,
                                                    adb_iperf_path=ue_iperf_adb_dir,
                                                    app_srv_lte_ip=app_srv_lte_ip,
                                                    analyzer_params=analyzer_params,
                                                    verification_delay=verification_delay)
            logger.info("Factory prepared sender class on ue_pc and receiver on app_server. "
                        "Prepared uplink data transmission.")

        else:
            receiver = ue_pc_server.IperfDataTransfer(ue_name=ue_name,
                                                      dt_name=dt_name,
                                                      dt_protocol=dt_definition.protocol,
                                                      dt_direction=dt_definition.direction,
                                                      ue_pc_instance=ue_pc,
                                                      ue_id=ue_serial_number,
                                                      ue_ip=ue_ip,
                                                      ue_type=ue_type,
                                                      command_tail=receiver_cmd_tail,
                                                      adb_iperf_path=ue_iperf_adb_dir,
                                                      app_srv_lte_ip=app_srv_lte_ip,
                                                      analyzer_params=analyzer_params,
                                                      iperf_version=ue_iperf_version,
                                                      verification_delay=verification_delay)
            sender = app_server.IperfDataTransfer(app_server_ip=app_srv_hostname,
                                                  app_server_username=app_srv_username,
                                                  app_server_password=app_srv_password,
                                                  app_server_lte_ip=app_srv_lte_ip,
                                                  logger=logger,
                                                  command_tail=sender_cmd_tail,
                                                  analyzer_params=analyzer_params)
            logger.info("Factory prepared sender class on app_server and receiver on ue_pc. "
                        "Prepared downlink data transmission.")
    else:
        raise NotImplementedError(
            "Data transfer protocol:%s is not supported by QualcommUe plugin" % dt_definition.protocol)
    return sender, receiver


def get_logs_path(data_transfer_name, ue_name):
    """
    :param data_transfer_name:     data_transfer_name
    :param ue_name:                ue_name
    """
    logs_location = core_logging.logging_path
    logfile = "app_server_" + ("default" if not ue_name else ue_name) + "_" + (
        "default" if not data_transfer_name else data_transfer_name) + ".txt"
    logs_path = os.path.join(logs_location, logfile)
    return logs_path


def get_source_and_target_ip(dt_direction, app_srv_lte_ip, ue_ip):
    """
    :param dt_direction:    dt_direction
    :param app_srv_lte_ip:  app_srv_lte_ip
    :param ue_ip:           ue_ip
    """
    target_ip = app_srv_lte_ip if dt_direction.upper() == "UL" else ue_ip
    source_ip = ue_ip if dt_direction.upper() == "UL" else app_srv_lte_ip
    return source_ip, target_ip


def validate_params_consistency(ue_type, dt_definition, ue_iperf_adb_dir, ue_serial_number):
    """
    :param ue_type:             <"LINUX", "ANDROID">
    :param dt_definition:       data transfer definition
    :param ue_iperf_adb_dir:    ue_iperf_adb_dir
    :param ue_serial_number:    ue_serial_number
    """
    ue_types = ["LINUX", "ANDROID"]

    if ue_type.upper() not in ue_types:
        raise DataTransferCreationException(
            "Incorrect UE type. Correct values are: LINUX or ANDROID")

    if ue_type.upper() == "ANDROID" and not (ue_iperf_adb_dir or ue_serial_number):
        raise DataTransferCreationException(
            "If UE type is set to Android fields iperf_adb_dir and adb_id shouldn't be empty.")

    if dt_definition.direction.upper() == 'UL' and ue_type == "LINUX" and 'interval' in dt_definition.protocol_details:
        raise DataTransferCreationException(
            "\'interval\' param is supported only for DL ping and UL ping for ue_type=ANDROID. It is not supported for UL ping ue_type=LINUX")
    try:
        assert dt_definition.direction.upper() in ['UL', 'DL']
        assert dt_definition.protocol.upper() in ['ICMP', 'TCP', 'UDP']
    except AssertionError as e:
        raise DataTransferCreationException("Unsupported data transfer param(s): " + str(e))
    verify_bandwidth(dt_definition)


def verify_bandwidth(dt_definition):
    """
    Verify bandwidth.

    :param dt_definition:       data transfer definition
    """
    # workaround for unfounded convention implemented by android plugin
    if dt_definition.protocol == 'udp' and 'bandwidth' not in dt_definition.protocol_details:
        dt_definition.protocol_details['bandwidth'] = str(
            int(dt_definition.throughput)) + UNIT_OF_DT_DEFINITION_THROUGHPUT

    if 'bandwidth' in dt_definition.protocol_details:
        try:
            normalized_bandwidth = param_checker.tput_user_value2normalized(
                dt_definition.protocol_details.get('bandwidth'))
            dt_definition.protocol_details['bandwidth'] = str(
                int(normalized_bandwidth)) + UNIT_OF_DT_DEFINITION_BANDWIDTH
        except ValueError as exp:
            message = "Incorrect bandwidth parameter. "
            message += str(exp)
            raise DataTransferCreationException(message)
